const GREEK_BASES = GREEK_BASE_LIST.map((w,i)=>({
  id:`greek_${i}`,
  stage:(GREEK_BASE_INFO[w]?.stage || null),
  form:w,
  display:w,
  bound:(GREEK_BASE_INFO[w]?.bound || false),
  meaning:(GREEK_BASE_INFO[w]?.meaning || ""),
  pos:(GREEK_BASE_INFO[w]?.pos || ["noun","adj","verb"]),
  examples:(GREEK_BASE_INFO[w]?.examples || [])
}));

window.MORPHEMES = {
  prefixes: PREFIXES,
  suffixes: SUFFIXES,
  bases: [
    ...CORE_BASES.map(b => ({ ...b, display:b.form, group:"core" })),
    ...ANGLO_BASES.map(b => ({ ...b, group:"anglo" })),
    ...LATIN_BASES.map(b => ({ ...b, group:"latin" })),
    ...GREEK_BASES.map(b => ({ ...b, group:"greek" }))
  ]
};
window.PREFIXES = PREFIXES;
window.SUFFIXES = SUFFIXES;
window.CORE_BASES = CORE_BASES;
window.ANGLO_BASES = ANGLO_BASES;
